const rows = [];
for (const item of $input.all()) {
  const r = item.json || {};
  const b = r.breakout_summary || {};
  if (r.status === 'ok' && (b.signal === 'strong' || b.signal === 'moderate')) {
    const h = r.hiring_intent || {};
    const g = r.google_ads || {};
    const c = r.contacts || {};
    rows.push({ json: {
      domain: r.domain,
      signal: b.signal,
      score: b.score,
      reasons: (b.reasons || []).join(' | '),
      hiring_status: h.hiring_status || null,
      open_roles: h.total_open_roles ?? null,
      roles_last_30_days: h.roles_posted_last_30_days ?? null,
      google_ads_in_sample: g.ads_returned ?? null,
      emails: (c.emails || []).join(', '),
      social_links: (c.social_links || []).join(', '),
      note: 'Estimate from public signals; not investment advice.'
    } });
  }
}
return rows;

const rows = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.code === 'payment_required' || r.status === 402) {
    rows.push({ json: { domain: r.domain || null, action: 'Free calls are used. Add a trial_token in Settings (POST https://gethirepulse.xyz/v1/trial), pay per call with an x402 client, or use the Apify Actor by card: ' + ((r.fiat_fallback && r.fiat_fallback.card_billing_url) || 'https://apify.com/hirepulse') } });
  } else if (r.status === 'insufficient_data') {
    rows.push({ json: { domain: r.domain, action: 'Not enough public data for a profile (not charged).' } });
  }
}
return rows;
